import{_ as o,o as l,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Keynote- From Busy to Impactful- Maximizing Ceph’s Collective Resources - Joseph Mundackal","description":"","frontmatter":{"title":"Keynote- From Busy to Impactful- Maximizing Ceph’s Collective Resources - Joseph Mundackal","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","分布式存储","社区治理","开源项目","高可用性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Keynote_-_From_Busy_to_Impactful_-_Maximizing_Ceph_s_Collective_Resources_-_Joseph_Mundackal.md","filePath":"posts/2025/Keynote_-_From_Busy_to_Impactful_-_Maximizing_Ceph_s_Collective_Resources_-_Joseph_Mundackal.md","lastUpdated":1780459816000}'),a={name:"posts/2025/Keynote_-_From_Busy_to_Impactful_-_Maximizing_Ceph_s_Collective_Resources_-_Joseph_Mundackal.md"};function r(s,e,n,_,p,u){return l(),t("div",null,[...e[0]||(e[0]=[i('<h3 id="ceph-社区会议纪要-从忙碌到影响力的转变" tabindex="-1">Ceph 社区会议纪要：从忙碌到影响力的转变 <a class="header-anchor" href="#ceph-社区会议纪要-从忙碌到影响力的转变" aria-label="Permalink to &quot;Ceph 社区会议纪要：从忙碌到影响力的转变&quot;">​</a></h3><p><strong>发言人</strong>：Joseph Mundiel（Bloomberg SE基础设施团队，Ceph基金会成员）<br><strong>会议主题</strong>：如何在Ceph社区中实现“影响力优先”而非“忙碌优先”</p><h4 id="一、背景与bloomberg的ceph实践" tabindex="-1"><strong>一、背景与Bloomberg的Ceph实践</strong> <a class="header-anchor" href="#一、背景与bloomberg的ceph实践" aria-label="Permalink to &quot;**一、背景与Bloomberg的Ceph实践**&quot;">​</a></h4><ol><li><p><strong>Bloomberg的Ceph应用</strong>：</p><ul><li>Ceph作为Bloomberg数据基础设施的核心，支撑全球金融分析和研究管道的24/7运行。</li><li>在Block存储方面，通过OpenStack + Ceph支持企业级规模，拥有近百万虚拟CPU，数百PB原始存储，跨多可用区。</li><li>在Object存储方面，运行地理复制的Ceph集群，使用最新版本的功能，如RGW的账户管理、通知机制。</li><li>Bloomberg有专职团队向社区提交Bug修复、功能开发，并赞助Ceph活动及基金会。</li></ul></li><li><p><strong>个人历程</strong>：</p><ul><li>7年前开始接触Ceph，从生产环境支持逐步扩展到组建内部团队，专注于源码构建、性能调优和自动化运维。</li><li>目前角色：Ceph指导委员会成员，代表Bloomberg参与基金会决策。</li></ul></li></ol><h4 id="二、核心议题-从-忙碌-到-影响力" tabindex="-1"><strong>二、核心议题：从&quot;忙碌&quot;到&quot;影响力&quot;</strong> <a class="header-anchor" href="#二、核心议题-从-忙碌-到-影响力" aria-label="Permalink to &quot;**二、核心议题：从&quot;忙碌&quot;到&quot;影响力&quot;**&quot;">​</a></h4><ol><li><p><strong>挑战反思</strong>：</p><ul><li>社区成员需要在有限的时间内最大化产出。</li><li>Ceph社区活跃，但“动作”并不总是等同于“进展”。</li><li>关键问题：是否在解决真实用户痛点？新功能是否满足实际需求？资源是否分散？</li></ul></li><li><p><strong>解决方案方向</strong>：</p><ul><li><strong>共享愿景</strong>：对齐优先级，投资核心基建（如CI/CD、测试框架、文档）。</li><li><strong>资金管理</strong>：基金会通过资助申请表支持紧急需求，强调“明智投资”。</li></ul></li></ol><h4 id="三、行动计划与呼吁" tabindex="-1"><strong>三、行动计划与呼吁</strong> <a class="header-anchor" href="#三、行动计划与呼吁" aria-label="Permalink to &quot;**三、行动计划与呼吁**&quot;">​</a></h4><ol><li><p><strong>社区行动建议</strong>：</p><ul><li>开发者应提问“为谁构建？影响如何衡量？”</li><li>基金会支持提交资助请求需说明紧迫性和预期影响。</li></ul></li><li><p><strong>参会者思考题</strong>：</p><ul><li>当前工作的意义是什么？目标用户是谁？</li><li>如何量化影响力？</li></ul></li></ol><h4 id="四、其他信息" tabindex="-1"><strong>四、其他信息</strong> <a class="header-anchor" href="#四、其他信息" aria-label="Permalink to &quot;**四、其他信息**&quot;">​</a></h4><ul><li><strong>招聘启事</strong>：Bloomberg招募Ceph企业级规模开发人才。</li><li><strong>资源链接</strong>：基金会资助申请表。</li></ul><p><strong>会议总结</strong>：Joseph Mundiel呼吁社区从“忙碌文化”转向“影响力驱动”，通过共享目标、资源聚焦和结果导向，推动Ceph在稳定性、用户体验和生态可持续性上的长期成功。</p>',11)])])}const g=o(a,[["render",r]]);export{c as __pageData,g as default};
